<?php
declare(strict_types=1);requireRole('social-service-officer');require_once __DIR__.'/../../config/database.php';$activePage='beneficiaries';$beneficiaries=[];$notice='';
try{$user=database()->prepare('SELECT district_id,ds_division_id FROM users WHERE id=:id');$user->execute(['id'=>$_SESSION['user_id']]);$scope=$user->fetch();if(!$scope||!$scope['ds_division_id'])$notice='Your account is not assigned to a DS Division yet.';else{$s=database()->prepare('SELECT b.*,d.name district,ds.name ds_name,gn.name gn_name,TIMESTAMPDIFF(YEAR,b.date_of_birth,CURDATE()) age FROM beneficiaries b JOIN districts d ON d.id=b.district_id JOIN ds_divisions ds ON ds.id=b.ds_division_id JOIN gn_divisions gn ON gn.id=b.gn_division_id WHERE b.ds_division_id=:ds AND b.status="active" ORDER BY b.full_name');$s->execute(['ds'=>$scope['ds_division_id']]);$beneficiaries=$s->fetchAll();}}catch(PDOException $e){error_log($e->getMessage());$notice='Beneficiary registry is unavailable.';}
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Beneficiary Management | WIDMS</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="assets/css/admin-dashboard.css" rel="stylesheet"></head><body><?php require __DIR__.'/../../includes/social-service-officer-sidebar.php';?><div class="admin-shell"><header class="topbar"><div class="d-flex align-items-center gap-3"><button class="menu-button" id="menu-button">&#9776;</button><h1>Beneficiary Management</h1></div></header><main class="dashboard-content beneficiary-page"><?php if($notice):?><div class="alert alert-info"><?=htmlspecialchars($notice,ENT_QUOTES,'UTF-8')?></div><?php endif;?><section class="beneficiary-section"><div class="beneficiary-toolbar"><h2>Registered Beneficiaries — My Division</h2><label><span class="visually-hidden">Search beneficiaries</span><input id="beneficiary-search" type="search" placeholder="Search by name or NIC..."></label></div><div class="beneficiary-table-card"><div class="beneficiary-table-wrap"><table class="beneficiary-table" id="beneficiary-table"><thead><tr><th>Name</th><th>NIC</th><th>Age</th><th>District</th><th>DS Division</th><th>GN Division</th><th>Phone</th><th>Disability</th></tr></thead><tbody><?php if(!$beneficiaries):?><tr><td colspan="8" class="beneficiary-empty">No registered beneficiaries available in your division.</td></tr><?php else:foreach($beneficiaries as $b):?><tr><td><strong><?=htmlspecialchars($b['full_name'],ENT_QUOTES,'UTF-8')?></strong></td><td><?=htmlspecialchars($b['nic'],ENT_QUOTES,'UTF-8')?></td><td><?=(int)$b['age']?></td><td><?=htmlspecialchars($b['district'],ENT_QUOTES,'UTF-8')?></td><td><?=htmlspecialchars($b['ds_name'],ENT_QUOTES,'UTF-8')?></td><td><?=htmlspecialchars($b['gn_name'],ENT_QUOTES,'UTF-8')?></td><td><?=htmlspecialchars($b['phone']?:'—',ENT_QUOTES,'UTF-8')?></td><td><?=htmlspecialchars($b['disability'],ENT_QUOTES,'UTF-8')?></td></tr><?php endforeach;endif;?></tbody></table></div></div></section></main></div><script src="assets/js/admin-dashboard.js"></script><script>document.getElementById('beneficiary-search')?.addEventListener('input',e=>document.querySelectorAll('#beneficiary-table tbody tr').forEach(r=>r.hidden=!r.textContent.toLowerCase().includes(e.target.value.toLowerCase())));</script></body></html>
